                                                                                                                                                                                                     
  CREATE TABLE "CHECK_PLAN"                                                                                                                                                               
   (	"PLAN_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                          
	"CREATION_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                               
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                          
	"UPDATED_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                
	"REMARK" NVARCHAR2(512),                                                                                                                                                                            
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                 
	"START_DATE" DATE,                                                                                                                                                                                  
	"END_DATE" DATE,                                                                                                                                                                                    
	"INTERVAL" NUMBER(10,0),                                                                                                                                                                            
	"FREQ" NVARCHAR2(32),                                                                                                                                                                               
	"DAY_MONTH" NVARCHAR2(100),                                                                                                                                                                         
	"DAY_WEEK" NVARCHAR2(100),                                                                                                                                                                          
	"HOUR" NVARCHAR2(52),                                                                                                                                                                               
	"FIRST_START_TIME" NVARCHAR2(100),                                                                                                                                                                  
	"FIRST_END_TIME" NVARCHAR2(100),                                                                                                                                                                    
	"SECOND_START_TIME" NVARCHAR2(100),                                                                                                                                                                 
	"SECOND_END_TIME" NVARCHAR2(100),                                                                                                                                                                   
	"CRON" NVARCHAR2(255),                                                                                                                                                                              
	"NEXT_EXECUTE" DATE,                                                                                                                                                                                
	"PREV_EXECUTE" DATE,                                                                                                                                                                                
	"DEL_FLAG" NUMBER(1,0) DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                   
	"IS_ENABLE" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE,                                                                                                                                                  
	"PREVIOUS_SHIFT" NVARCHAR2(20),                                                                                                                                                                     
	"PLAN_NAME" NVARCHAR2(200),                                                                                                                                                                         
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                       
	"INTERVAL_CYCLE_TEXT" NVARCHAR2(256),                                                                                                                                                               
	"CYCLE_DAY_START" NVARCHAR2(20),                                                                                                                                                                    
	"CYCLE_DAY_END" NVARCHAR2(20),                                                                                                                                                                      
	 PRIMARY KEY ("PLAN_ID")                                                                                                                                                                            
  USING INDEX  ENABLE                                                                                                                                                                                
   ) ;                                                                                                                                                                                               

